// Content with portions generated by generative AI platform
package org.eclipse.kura.core.token.jwt.issuer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.eclipse.kura.KuraErrorCode;
import org.eclipse.kura.KuraException;
import org.eclipse.kura.core.testutil.pki.TestCA.TestCAException;
import org.eclipse.kura.core.token.jwt.common.AbstractJwtScenario;
import org.eclipse.kura.core.token.jwt.common.IssuingConfig;
import org.eclipse.kura.security.token.TokenIssueRequest;
import org.junit.Test;

public class ReservedClaimsTest extends AbstractJwtScenario {

    private static final List<String> RESERVED_CLAIMS = List.of("iss", "sub", "aud", "exp", "nbf", "iat", "jti");

    private final Map<String, Exception> failuresByClaim = new LinkedHashMap<>();
    private final List<String> acceptedReservedClaims = new ArrayList<>();

    @Test
    public void everyReservedClaimIsRejectedAsABadRequest() throws TestCAException {
        givenAnIssuerWithASigningKey();

        whenATokenIsRequestedWithEachReservedClaim();

        thenEveryReservedClaimWasRejectedAsABadRequest();
        thenNoReservedClaimWasAccepted();
    }

    @Test
    public void everyRejectionNamesTheOffendingClaim() throws TestCAException {
        givenAnIssuerWithASigningKey();

        whenATokenIsRequestedWithEachReservedClaim();

        thenEveryRejectionNamesTheOffendingClaim();
    }

    @Test
    public void aClaimWhoseNameOnlyResemblesAReservedOneIsAccepted() throws TestCAException {
        givenAnIssuerWithASigningKey();

        whenATokenIsRequestedWithClaim("issuer", "not-the-iss-claim");

        thenATokenIsIssued();
        thenIssuedTokenHasStringClaim("issuer", "not-the-iss-claim");
    }

    @Test
    public void theReservedClaimsAreOwnedByTheService() throws TestCAException {
        givenAnIssuerWithASigningKey();

        whenATokenIsRequestedWithClaim("role", "admin");

        thenIssuedTokenHasStringClaim("iss", DEFAULT_ISSUER);
        thenIssuedTokenHasStringClaim("sub", TEST_IDENTITY);
        thenIssuedTokenHasStringClaim("role", "admin");
    }

    private void givenAnIssuerWithASigningKey() throws TestCAException {
        givenKeystorePrivateKeyEntry(SIGNING_ALIAS, 0);
        givenTheIssuerIsBoundToTheKeystore();
        givenTheIssuerIsActivatedWith(IssuingConfig.defaults().withSigningKeyAlias(SIGNING_ALIAS));
    }

    private void whenATokenIsRequestedWithEachReservedClaim() {
        for (final String reservedClaim : RESERVED_CLAIMS) {
            whenATokenIsIssued(TokenIssueRequest.builder(TEST_IDENTITY) //
                    .claim(reservedClaim, "injected-by-the-caller") //
                    .build());

            this.failuresByClaim.put(reservedClaim, issuingFailure());

            if (issuedToken() != null) {
                this.acceptedReservedClaims.add(reservedClaim);
            }
        }
    }

    private void whenATokenIsRequestedWithClaim(final String name, final Object value) {
        whenATokenIsIssued(TokenIssueRequest.builder(TEST_IDENTITY) //
                .claim(name, value) //
                .build());
    }

    private void thenEveryReservedClaimWasRejectedAsABadRequest() {
        for (final String reservedClaim : RESERVED_CLAIMS) {
            final Exception failure = this.failuresByClaim.get(reservedClaim);

            assertNotNull("the reserved claim '" + reservedClaim + "' was not rejected", failure);
            assertTrue("the reserved claim '" + reservedClaim + "' was rejected with "
                    + failure.getClass().getName() + " instead of a KuraException", failure instanceof KuraException);
            assertEquals("wrong error code for the reserved claim '" + reservedClaim + "'", KuraErrorCode.BAD_REQUEST,
                    ((KuraException) failure).getCode());
        }
    }

    private void thenNoReservedClaimWasAccepted() {
        assertEquals("reserved claims accepted by the issuer", List.of(), this.acceptedReservedClaims);
    }

    private void thenEveryRejectionNamesTheOffendingClaim() {
        for (final String reservedClaim : RESERVED_CLAIMS) {
            final String message = this.failuresByClaim.get(reservedClaim).getMessage();

            assertTrue("the rejection message '" + message + "' does not name the claim '" + reservedClaim + "'",
                    message.contains("'" + reservedClaim + "'"));
        }
    }

}
